<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes">
  <meta name="description" content="AI 모델 qwen3-235b-a22b를 표현하는 미디어아트 웹페이지">
  <title>qwen3-235b-a22b - 미디어아트 표현</title>
  <style>
    /* 기본 리셋 및 접근성 기반 스타일 */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Segoe UI', Arial, sans-serif;
      background-color: #000;
      color: #fff;
      overflow: hidden;
      height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      line-height: 1.6;
      transition: background-color 0.5s ease;
      position: relative;
      padding: 20px;
      text-align: center;
    }

    /* 시각적 요소 */
    .neural-canvas {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      z-index: -1;
    }

    .node {
      position: absolute;
      width: 6px;
      height: 6px;
      background: #4fc3f7;
      border-radius: 50%;
      box-shadow: 0 0 10px #4fc3f7;
      opacity: 0.8;
      transition: all 0.3s ease;
    }

    .connection {
      position: absolute;
      height: 1px;
      background: #29b6f6;
      transform-origin: left center;
      opacity: 0.3;
      transition: opacity 0.3s ease;
    }

    /* 콘텐츠 영역 */
    .content {
      z-index: 10;
      max-width: 800px;
      padding: 20px;
      background-color: rgba(0, 0, 0, 0.6);
      border-radius: 12px;
      backdrop-filter: blur(10px);
    }

    h1 {
      font-size: 1.8rem;
      margin-bottom: 10px;
      color: #a0d8f1;
      text-shadow: 0 0 10px #4fc3f7;
    }

    .model-id {
      font-family: 'Courier New', monospace;
      font-size: 1.2rem;
      color: #e0f7fa;
      background: #00334d;
      padding: 8px 12px;
      border-radius: 6px;
      margin: 15px 0;
      display: inline-block;
      letter-spacing: 0.8px;
    }

    p {
      font-size: 1rem;
      margin: 10px 0;
      color: #e0f7fa;
    }

    .controls {
      margin-top: 20px;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
    }

    button {
      background: #0288d1;
      color: white;
      border: none;
      padding: 10px 16px;
      border-radius: 6px;
      cursor: pointer;
      font-size: 0.9rem;
      transition: background 0.3s ease;
    }

    button:hover, button:focus {
      background: #03a4fa;
      outline: 2px solid #81d4fa;
    }

    button:active {
      transform: scale(0.98);
    }

    /* 감소된 동작 선호 설정 지원 */
    @media (prefers-reduced-motion: reduce) {
      * {
        animation: none !important;
        transition: none !important;
      }
      .node, .connection {
        opacity: 0.6 !important;
      }
    }

    /* 접근성: 키보드 탐색을 위한 포커스 스타일 */
    button:focus-visible {
      outline: 2px solid #81d4fa;
